def build_challenge():
    from lexicon import NAMES
    def labels(values):
        return [{'mcId': c, 'label': NAMES[c]} for c in sorted(values)]
    rows = []
    for i, (description, offered, reason) in enumerate(CASES, 1):
        for source in NAMES:
            rows.append({'item_id': f'own-v3-challenge-{i:02d}-{source}',
                         'group_id': f'own-v3-challenge-{i:02d}',
                         'description': description, 'mcId': source,
                         'found_microcategories': labels(set(offered) - {source}),
                         'offered_microcategories': offered,
                         'rationale': reason, 'provenance': 'authored_scope_probe_v3',
                         'annotation_status': 'scenario_defined_not_independently_reviewed'})
    return rows
